#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char path[PATH_MAX];
    FILE *fp;

    // Validate inputs
    if (!iface || !var || !name) {
        return -1;
    }

    // Format the file path safely
    if (snprintf(path, sizeof(path), var, iface) < 0) {
        return -1;
    }

    // Open the file for writing
    fp = fopen(path, "w");
    if (!fp) {
        return -1;
    }

    // Write the value to the file
    if (fprintf(fp, "%u\n", val) < 0) {
        fclose(fp);
        return -1;
    }

    // Close the file
    if (fclose(fp) != 0) {
        return -1;
    }

    return 0;
}
